from common import p,step,svg,text,line,graph

def add_redox(b):
    code='R3.2'
    def mc(level,diff,title,stem,correct,distractors,reason,**kw):
        return b.add(code,level,diff,title,stem,correct=correct,distractors=distractors,reasoning=reason,**kw)
    def q(level,diff,title,stem,*parts,**kw):
        return b.add(code,level,diff,title,stem,parts=list(parts),**kw)
    mc('sl','easy','Chromium in a polyatomic ion',r'What is the oxidation state of chromium in $\mathrm{Cr_2O_7^{2-}}$?',r'$+6$',[r'$+3$',r'$+7$',r'$-2$'],r'With oxygen at $-2$, $2x+7(-2)=-2$, giving $x=+6$. The total is the ion charge, not zero.')
    q('sl','easy','Tracking the transfer',r'Zinc reacts with aqueous copper(II) ions: $\mathrm{Zn(s)+Cu^{2+}(aq)\rightarrow Zn^{2+}(aq)+Cu(s)}$.',p('Identify the species oxidized and the reducing agent, explaining the link.',step(r'$\mathrm{Zn}$ is oxidized because it loses two electrons.'),step('Zinc is therefore the reducing agent: it supplies the electrons that reduce the copper(II) ions.')),p('Write the reduction half-equation.',step(r'$\mathrm{Cu^{2+}+2e^-\rightarrow Cu}$.')))
    q('sl','medium','One compound, two redox roles',r'Hydrogen peroxide decomposes according to $\mathrm{2H_2O_2(aq)\rightarrow 2H_2O(l)+O_2(g)}$.',p('State the oxidation state of oxygen in each of the three species.',step(r'$\mathrm{H_2O_2}$: $-1$; $\mathrm{H_2O}$: $-2$; $\mathrm{O_2}$: $0$.')),p('Explain why this is both oxidation and reduction of the same starting compound.',step('Some peroxide oxygen gains electrons in oxidation-state terms, changing from -1 to -2.'),step('Other peroxide oxygen loses electrons in oxidation-state terms, changing from -1 to 0. Thus peroxide supplies both oxidized and reduced atoms.')))
    q('sl','hard','Balancing an acidic redox reaction',r'In acidic solution, $\mathrm{MnO_4^-}$ is reduced to $\mathrm{Mn^{2+}}$ while $\mathrm{Fe^{2+}}$ is oxidized to $\mathrm{Fe^{3+}}$.',p('Write the reduction half-equation.',step(r'Balance oxygen and hydrogen with $4\mathrm{H_2O}$ and $8\mathrm{H^+}$.','M1'),step(r'$\mathrm{MnO_4^-+8H^++5e^-\rightarrow Mn^{2+}+4H_2O}$.')),p('Combine the half-equations into an overall ionic equation.',step(r'Multiply $\mathrm{Fe^{2+}\rightarrow Fe^{3+}+e^-}$ by 5.','M1'),step(r'$\mathrm{MnO_4^-+8H^++5Fe^{2+}\rightarrow Mn^{2+}+4H_2O+5Fe^{3+}}$.')),notes='Both atom totals and total charge (+17 on each side of the final equation) checked.')
    q('sl','medium','A displacement evidence table',r'Tests show that metal P displaces Q from $\mathrm{Q^{2+}}$ solution; Q displaces R from $\mathrm{R^{2+}}$ solution; R does not displace P from $\mathrm{P^{2+}}$ solution. All three metals form $2+$ ions.',p('Rank the metals from easiest to hardest to oxidize.',step('P, then Q, then R.'),step('A metal that displaces another metal ion is itself oxidized, so the first two positive tests establish P > Q > R.')),p(r'Predict the result of putting P into $\mathrm{R^{2+}}$ solution and write the ionic equation.',step('A reaction should occur.'),step(r'$\mathrm{P(s)+R^{2+}(aq)\rightarrow P^{2+}(aq)+R(s)}$.')),question_type='data-based')
    mc('sl','medium','Halogen displacement',r'Chlorine is easier to reduce than bromine. What occurs when chlorine is added to aqueous bromide ions?',r'$\mathrm{Cl_2+2Br^-\rightarrow 2Cl^-+Br_2}$',[r'$\mathrm{Cl_2+Br^-\rightarrow Cl^-+Br_2}$',r'$\mathrm{2Cl^-+Br_2\rightarrow Cl_2+2Br^-}$','No redox reaction is possible.'],r'Chlorine accepts two electrons and bromide loses electrons. The balanced result forms chloride and bromine.')
    q('sl','medium','Hydrogen released from a metal',r'$0.486\,\mathrm{g}$ magnesium reacts completely with excess dilute hydrochloric acid. Use $M(\mathrm{Mg})=24.31\,\mathrm{g\,mol^{-1}}$ and a gas molar volume of $22.7\,\mathrm{dm^3\,mol^{-1}}$ at the stated STP.',p('Write an ionic equation and identify the oxidizing agent.',step(r'$\mathrm{Mg(s)+2H^+(aq)\rightarrow Mg^{2+}(aq)+H_2(g)}$.'),step(r'$\mathrm{H^+}$ is the oxidizing agent because it is reduced.')),p('Calculate the volume of hydrogen at STP.',step(r'$n(\mathrm{H_2})=n(\mathrm{Mg})=0.486/24.31=0.01999\,\mathrm{mol}$.','M1'),step(r'$V=0.01999\times22.7=0.454\,\mathrm{dm^3}$.')))
    mc('sl','medium','Electrode roles across two cells',r'Which statement is true for both a discharging voltaic cell and an electrolytic cell?',r'Oxidation occurs at the anode.',['The anode is negative.','The cathode is positive.','The cell reaction is spontaneous.'],r'Anode and cathode are defined by oxidation and reduction respectively. Their polarities differ between voltaic and electrolytic cells; an electrolytic reaction is driven by an external supply.')
    body=text(400,28,'A zinc–copper cell',20)
    body+=line(90,130,90,305)+line(90,305,310,305)+line(310,305,310,130)+line(490,130,490,305)+line(490,305,710,305)+line(710,305,710,130)
    body+='<path d="M95 202 H305 V300 H95 Z M495 202 H705 V300 H495 Z" fill="#dff0f4"/>'
    body+='<path d="M265 230 V145 Q265 115 295 115 H505 Q535 115 535 145 V230" fill="none" stroke="#8aa7b5" stroke-width="18"/>'
    body+=text(400,160,'salt bridge',15)+line(160,195,160,70)+line(640,195,640,70)+line(160,70,350,70)+line(450,70,640,70)
    body+='<rect x="150" y="175" width="20" height="90" fill="#a7b5bc" stroke="#31556b"/><rect x="630" y="175" width="20" height="90" fill="#c7a185" stroke="#31556b"/>'
    body+='<rect x="350" y="48" width="100" height="44" rx="5" fill="white" stroke="#31556b" stroke-width="2"/>'
    body+=text(400,77,'V',18)+text(220,242,'Zn(s)',17)+text(575,242,'Cu(s)',17)+text(200,280,'Zn²⁺(aq)',16)+text(600,280,'Cu²⁺(aq)',16)
    q('sl','medium','Charge flow in a voltaic cell',r'The cell shown operates spontaneously as $\mathrm{Zn+Cu^{2+}\rightarrow Zn^{2+}+Cu}$. The salt bridge contains potassium nitrate.',p('Identify the anode and cathode, including their polarities.',step('Zinc is the negative anode, where oxidation occurs.'),step('Copper is the positive cathode, where reduction occurs.')),p('State the direction of electron flow and explain one salt-bridge ion movement.',step('Electrons flow through the external circuit from zinc to copper.'),step(r'Nitrate ions migrate towards the zinc half-cell to balance the accumulating $\mathrm{Zn^{2+}}$; alternatively potassium ions migrate towards the copper half-cell as $\mathrm{Cu^{2+}}$ is removed.')),p('Explain why electrons do not travel through the salt bridge.',step('Charge in the solution and salt bridge is carried by mobile ions; electrons move through the metal circuit.')),diagram=svg(body,800,350))
    q('sl','medium','Reversing a rechargeable cell',r'A model rechargeable cell has the following discharge half-equations: $\mathrm{M\rightarrow M^{2+}+2e^-}$ and $\mathrm{X+2e^-\rightarrow X^{2-}}$. The electrode reactions are reversible under the operating conditions.',p('Write both half-equations during charging.',step(r'$\mathrm{M^{2+}+2e^-\rightarrow M}$.'),step(r'$\mathrm{X^{2-}\rightarrow X+2e^-}$.')),p('Explain the direction of energy conversion during charging and why a power source is required.',step('Electrical energy is converted into stored chemical energy.'),step('The supply drives the reverse of the spontaneous discharge reaction.')))
    q('sl','medium','Electrolysis of a molten chloride',r'Molten magnesium chloride is electrolysed using inert electrodes.',p('Write the cathode and anode half-equations.',step(r'Cathode: $\mathrm{Mg^{2+}+2e^-\rightarrow Mg}$.'),step(r'Anode: $\mathrm{2Cl^-\rightarrow Cl_2+2e^-}$.')),p('Explain why the molten material conducts but the solid does not.',step('The ions are mobile in the melt and transport charge.'),step('In the solid lattice the ions are fixed in place and cannot provide bulk charge transport.')),p('State which electrode is connected to the negative terminal of the power supply.',step('The cathode is connected to the negative terminal.')))
    mc('sl','easy','How current crosses an electrolyte',r'Which description correctly accounts for current inside molten sodium chloride during electrolysis?',r'Positive and negative ions move in opposite directions.',['Only electrons move through the liquid.','Positive ions move through the liquid but negative ions remain fixed.','Neutral sodium atoms carry charge between electrodes.'],r'The molten electrolyte contains mobile cations and anions. They carry charge towards the cathode and anode respectively; electrons carry charge in the external wires.')
    q('sl','medium','Stopping alcohol oxidation at an aldehyde',r'Propan-1-ol can be oxidized first to propanal and then to propanoic acid. Use $[\mathrm{O}]$ for supplied oxidizing equivalents.',p('Write an equation for each oxidation step.',step(r'$\mathrm{CH_3CH_2CH_2OH+[O]\rightarrow CH_3CH_2CHO+H_2O}$.'),step(r'$\mathrm{CH_3CH_2CHO+[O]\rightarrow CH_3CH_2COOH}$.')),p('Explain why distillation can favour collection of the aldehyde whereas reflux with excess oxidant favours the acid.',step('Distillation removes the volatile aldehyde as it forms, reducing its contact with oxidant.'),step('Reflux returns vapour to the flask and permits continued reaction with excess oxidant.')))
    q('sl','medium','Oxidation of a secondary alcohol',r'Butan-2-ol is heated under suitable oxidizing conditions.',p('Give the product name and a balanced equation using [O].',step('The product is butan-2-one.'),step(r'$\mathrm{CH_3CH(OH)CH_2CH_3+[O]\rightarrow CH_3COCH_2CH_3+H_2O}$.')),p('Explain the change in bonding around the carbon originally bonded to the hydroxy group.',step('A C–H bond at that carbon and an O–H bond are lost while a carbon–oxygen double bond forms; this is oxidation.')))
    mc('sl','medium','A tertiary alcohol under mild oxidation',r'Under ordinary alcohol-oxidation conditions that convert butan-2-ol to a ketone, what is expected for 2-methylpropan-2-ol?',r'No comparable oxidation occurs without breaking a carbon–carbon bond.',['It forms 2-methylpropanal directly.','It forms butan-2-one without changing connectivity.','It must immediately form carbon dioxide and water.'],r'The carbon bearing the hydroxy group in a tertiary alcohol has no C–H bond. The usual conversion to a carbonyl cannot occur by simply removing hydrogen from that carbon and oxygen.')
    q('sl','medium','Reduction through carbonyl groups',r'Consider reduction of ethanoic acid to ethanol via ethanal, and reduction of propanone to propan-2-ol. Use $[\mathrm{H}]$ for supplied reducing equivalents.',p('Write the overall reduction equation for each starting compound.',step(r'$\mathrm{CH_3COOH+4[H]\rightarrow CH_3CH_2OH+H_2O}$.'),step(r'$\mathrm{CH_3COCH_3+2[H]\rightarrow CH_3CH(OH)CH_3}$.')),p('State the role of hydride in a suitable reduction reagent.',step(r'A hydride ion, $\mathrm{H^-}$, can supply hydrogen together with an electron pair to an electron-deficient carbonyl carbon. No detailed mechanism or reagent name is required.')))
    q('sl','medium','Hydrogenating an alkyne',r'But-2-yne undergoes complete hydrogenation with excess hydrogen under suitable catalytic conditions.',p('Write the overall equation and name the organic product.',step(r'$\mathrm{CH_3C\equiv CCH_3+2H_2\rightarrow CH_3CH_2CH_2CH_3}$.'),step('The product is butane.')),p(r'Calculate the amount of hydrogen required for $0.0750\,\mathrm{mol}$ but-2-yne and explain why this is a reduction.',step(r'$n(\mathrm{H_2})=2(0.0750)=0.150\,\mathrm{mol}$.','M1'),step('The organic compound gains hydrogen and its degree of unsaturation decreases.')))
    mc('ahl','easy','Reading reduction potentials',r'The standard reduction potentials are $\mathrm{A^{2+}/A}=-0.40\,\mathrm{V}$ and $\mathrm{B^{2+}/B}=+0.60\,\mathrm{V}$. Which species is the stronger oxidizing agent under standard conditions?',r'$\mathrm{B^{2+}}$',[r'$\mathrm{A^{2+}}$',r'$\mathrm{A}$',r'$\mathrm{B}$'],r'The more positive reduction potential indicates a stronger tendency for the oxidized species to gain electrons. Therefore $\mathrm{B^{2+}}$ is the stronger oxidizing agent.')
    q('ahl','medium','The reference half-cell',r'A metal/metal-ion electrode is connected to a standard hydrogen electrode to measure its standard electrode potential.',p('Describe the essential features of the standard hydrogen electrode.',step(r'Hydrogen gas at standard pressure, $100\,\mathrm{kPa}$, contacts an inert platinum electrode.'),step(r'The electrode contacts acid with hydrogen-ion activity 1, conventionally represented in this course as $1.0\,\mathrm{mol\,dm^{-3}}$, at the stated temperature (commonly $298\,\mathrm{K}$).')),p('Write the half-equation and state its assigned standard potential.',step(r'$\mathrm{2H^++2e^-\rightleftharpoons H_2}$; its assigned standard potential is $0.00\,\mathrm{V}$.')),notes='Distinguishes the conventional concentration model used in the course from the thermodynamic activity definition.')
    q('ahl','medium','Calculating a standard cell potential',r'Use $E^\circ(\mathrm{Cu^{2+}/Cu})=+0.34\,\mathrm{V}$ and $E^\circ(\mathrm{Zn^{2+}/Zn})=-0.76\,\mathrm{V}$.',p('Calculate the standard potential for a spontaneous zinc–copper cell and write the overall reaction.',step(r'$E^\circ_\mathrm{cell}=E^\circ_\mathrm{cathode}-E^\circ_\mathrm{anode}=0.34-(-0.76)$.','M1'),step(r'$E^\circ_\mathrm{cell}=+1.10\,\mathrm{V}$.'),step(r'$\mathrm{Zn+Cu^{2+}\rightarrow Zn^{2+}+Cu}$.')),p('Explain what the sign establishes and what it does not establish.',step('The positive value predicts thermodynamic favourability in the written direction under standard conditions.'),step('It does not by itself predict how rapidly the reaction occurs.')))
    q('ahl','hard','Balancing electrons without scaling voltage',r'A cell uses $\mathrm{Al^{3+}+3e^-\rightleftharpoons Al}$, $E^\circ=-1.66\,\mathrm{V}$, and $\mathrm{Ag^++e^-\rightleftharpoons Ag}$, $E^\circ=+0.80\,\mathrm{V}$.',p('Write the spontaneous overall equation and calculate its standard cell potential.',step(r'$\mathrm{Al+3Ag^+\rightarrow Al^{3+}+3Ag}$.'),step(r'$E^\circ_\mathrm{cell}=0.80-(-1.66)=+2.46\,\mathrm{V}$.','M1')),p('Explain why the silver potential is not multiplied by three.',step('Potential is energy per unit charge, an intensive quantity; multiplying a half-equation scales both energy and charge by the same factor.')),notes='Three electrons transferred per overall reaction. Potentials do not scale with stoichiometric coefficients.')
    q('ahl','medium','Gibbs energy from a cell',r'A standard cell reaction transfers two moles of electrons per mole of reaction and has $E^\circ_\mathrm{cell}=0.720\,\mathrm{V}$. Use $F=9.65\times10^4\,\mathrm{C\,mol^{-1}}$.',p('Calculate the standard Gibbs energy change in kJ mol^-1.',step(r'$\Delta G^\circ=-nFE^\circ=-2(9.65\times10^4)(0.720)$.','M1'),step(r'$\Delta G^\circ=-1.3896\times10^5\,\mathrm{J\,mol^{-1}}$.'),step(r'$\Delta G^\circ\approx-139\,\mathrm{kJ\,mol^{-1}}$.')),p('State the thermodynamic implication.',step('The negative standard Gibbs energy change means the written reaction is thermodynamically favourable under standard conditions.')))
    q('ahl','hard','Can copper(I) disproportionate?',r'Use $E^\circ(\mathrm{Cu^{2+}/Cu^+})=+0.15\,\mathrm{V}$ and $E^\circ(\mathrm{Cu^+/Cu})=+0.52\,\mathrm{V}$. Consider $\mathrm{2Cu^+\rightarrow Cu^{2+}+Cu}$.',p('Identify the reduction and oxidation half-equations.',step(r'Reduction: $\mathrm{Cu^++e^-\rightarrow Cu}$.'),step(r'Oxidation: $\mathrm{Cu^+\rightarrow Cu^{2+}+e^-}$.')),p('Calculate the standard potential and assess the proposed direction.',step(r'$E^\circ_\mathrm{cell}=0.52-0.15=+0.37\,\mathrm{V}$.','M1'),step('The positive value predicts disproportionation in the written direction under standard conditions.')))
    q('ahl','medium','Aqueous copper sulfate with inert electrodes',r'Aqueous copper(II) sulfate is electrolysed with inert electrodes. Under the specified conditions copper is deposited at the cathode and water is oxidized at the anode.',p('Write both electrode half-equations.',step(r'Cathode: $\mathrm{Cu^{2+}+2e^-\rightarrow Cu}$.'),step(r'Anode: $\mathrm{2H_2O\rightarrow O_2+4H^++4e^-}$.')),p('Predict the changes in solution colour and acidity as electrolysis continues.',step('The blue colour becomes paler as copper(II) ions are removed.'),step('Acidity increases because hydrogen ions are produced at the anode.')))
    q('ahl','medium','Replacing an inert anode with copper',r'An aqueous copper(II) sulfate electrolysis cell uses a copper anode and a copper cathode. Copper oxidation is the anode reaction and copper deposition is the cathode reaction.',p('Write the two half-equations and predict the changes in electrode masses.',step(r'Anode: $\mathrm{Cu\rightarrow Cu^{2+}+2e^-}$; its mass decreases.'),step(r'Cathode: $\mathrm{Cu^{2+}+2e^-\rightarrow Cu}$; its mass increases.')),p('Explain why the copper(II) concentration can remain approximately constant.',step('Copper(II) ions are produced and consumed in equal amounts for the same charge passed, provided these are the only electrode reactions.')))
    q('ahl','hard','Concentration affects anode products',r'With inert electrodes, an experiment gives chlorine at the anode when concentrated aqueous sodium chloride is electrolysed, but oxygen is the main anode product in a very dilute solution. Hydrogen is produced at the cathode in both experiments.',p('Write the observed anode half-equation in each case.',step(r'Concentrated chloride: $\mathrm{2Cl^-\rightarrow Cl_2+2e^-}$.'),step(r'Dilute solution: $\mathrm{2H_2O\rightarrow O_2+4H^++4e^-}$ (or the equivalent hydroxide equation).')),p('Explain why quoting standard potentials alone is insufficient to guarantee identical anode products in these experiments.',step('The experiments differ in concentration and need not be under standard conditions.'),step('There are competing chloride and water oxidation reactions; actual discharge also depends on electrode kinetics, so the supplied experimental observations must be respected.')),question_type='data-based')
    q('ahl','medium','Gas products in water electrolysis',r'Water is electrolysed using an electrolyte and electrodes for which hydrogen and oxygen are the only gaseous products. Both gases are collected at the same temperature and pressure.',p('Write balanced acidic-form half-equations.',step(r'Cathode: $\mathrm{4H^++4e^-\rightarrow 2H_2}$.'),step(r'Anode: $\mathrm{2H_2O\rightarrow O_2+4H^++4e^-}$.')),p('Predict the gas-volume ratio and explain a result lower than the predicted oxygen volume.',step(r'Hydrogen:oxygen is 2:1 because the balanced overall equation is $\mathrm{2H_2O\rightarrow 2H_2+O_2}$.'),step('A smaller collected oxygen volume could result from a leak, gas dissolving before collection, or another anode reaction; one specific plausible cause earns the mark.')))
    q('sl','hard','A redox titration from stoichiometry',r'An acidified $25.00\,\mathrm{cm^3}$ iron(II) sample requires $18.60\,\mathrm{cm^3}$ of $0.0200\,\mathrm{mol\,dm^{-3}}$ permanganate. The reaction is $\mathrm{MnO_4^-+8H^++5Fe^{2+}\rightarrow Mn^{2+}+4H_2O+5Fe^{3+}}$.',p('Calculate the iron(II) concentration.',step(r'$n(\mathrm{MnO_4^-})=0.0200\times0.01860=3.72\times10^{-4}\,\mathrm{mol}$.','M1'),step(r'$n(\mathrm{Fe^{2+}})=5(3.72\times10^{-4})=0.00186\,\mathrm{mol}$.','M1'),step(r'$[\mathrm{Fe^{2+}}]=0.00186/0.02500=0.0744\,\mathrm{mol\,dm^{-3}}$.')),p('Permanganate is intensely coloured and its reduced product is much paler. Explain how a persistent trace of its colour indicates the end point.',step('Once all the iron(II) has reacted, the next small excess of permanganate remains unreduced and produces a persistent colour.')),question_type='data-based')
    q('ahl','hard','What standard potential data establish',r'A student calculates a positive standard cell potential using standard reduction data, then claims the cell must show exactly this voltage in every concentration and at every temperature.',p('Evaluate the claim.',step('The calculation applies to the defined standard-state conditions at the temperature of the supplied data.'),step('Changing ion concentrations or temperature can change the actual cell potential, so the numerical claim is unjustified.')),p('State two experimental features needed for a reliable comparison with standard data.',step('Use the stated temperature and appropriate standard solution concentrations/activities.'),step('Use a high-resistance voltmeter and correct gas pressures where relevant, limiting current draw and associated changes.')))
    q('ahl','medium','Correcting an electroplating design',r'A student wants to copper-plate a steel spoon from aqueous copper(II) sulfate. The spoon has accidentally been connected to the positive terminal; a copper strip is connected to the negative terminal.',p('State the required correction and explain why it is necessary.',step('Connect the spoon to the negative terminal and the copper strip to the positive terminal.'),step('The spoon must be the cathode, where copper(II) ions gain electrons and deposit copper.')),p('Write the desired spoon reaction and the corresponding copper-strip reaction.',step(r'Spoon: $\mathrm{Cu^{2+}+2e^-\rightarrow Cu}$.'),step(r'Copper strip: $\mathrm{Cu\rightarrow Cu^{2+}+2e^-}$.')))
    assert len(b.questions)==60
